package com.starlight.greetings.application;
import com.starlight.greetings.web.ApiException; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.*; import org.springframework.dao.DuplicateKeyException; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service;
@Service public class JdbcSurveyMetricsService implements SurveyMetricsService {private final JdbcTemplate jdbc; public JdbcSurveyMetricsService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public Map<String,Object> survey(){var rows=jdbc.query("select url,starts_at,ends_at,enabled from survey_campaign where id=1",(rs,i)->new Object[]{rs.getString(1),rs.getTimestamp(2),rs.getTimestamp(3),rs.getBoolean(4)});if(rows.isEmpty()||!(Boolean)rows.get(0)[3]||((java.sql.Timestamp)rows.get(0)[1]).after(new java.sql.Timestamp(System.currentTimeMillis()))||!((java.sql.Timestamp)rows.get(0)[2]).after(new java.sql.Timestamp(System.currentTimeMillis())))return Map.of("active",false);return Map.of("active",true,"url",rows.get(0)[0]);}
 public Map<String,Object> event(Map<String,Object> input,String source){return record(input,"",source,false);} public Map<String,Object> surveyOpen(Map<String,Object> input,String source){if(!(Boolean)survey().get("active"))throw new ApiException(HttpStatus.CONFLICT,"SURVEY_CLOSED","설문 기간이 아닙니다.");return record(input,"survey_open",source,true);}
 private Map<String,Object> record(Map<String,Object> input,String forced,String source,boolean survey){String id=input.get("eventId") instanceof String v?v:null;String type=forced.isEmpty()?(input.get("eventType") instanceof String v?v:null):forced;String bridge=input.get("bridgeId") instanceof String v?v:null;String letter=input.get("letterId") instanceof String v?v:null;if(id==null||!id.matches("^[0-9a-fA-F-]{36}$"))throw bad("INVALID_EVENT_ID","이벤트 식별값을 확인해 주세요.");if(!Set.of("survey_open","qr_entry","letter_open","five_reached","signup_start","write_start").contains(type))throw bad("INVALID_EVENT_TYPE","이벤트 종류를 확인해 주세요.");String kind=null;if("letter_open".equals(type)){if(letter==null)throw bad("INVALID_LETTER","편지 정보를 확인해 주세요.");var letters=jdbc.query("select bridge_id,is_seed from letters where id=?::uuid and status='published'",(rs,i)->new Object[]{rs.getString(1),rs.getBoolean(2)},letter);if(letters.isEmpty())throw new ApiException(HttpStatus.NOT_FOUND,"LETTER_NOT_FOUND","편지를 찾을 수 없습니다.");bridge=(String)letters.get(0)[0];kind=(Boolean)letters.get(0)[1]?"seed":"member";}else if(!"survey_open".equals(type)&&bridge==null)throw bad("BRIDGE_REQUIRED","다리를 선택해 주세요.");try{int n=jdbc.update("insert into metric_events (id,event_type,bridge_id,letter_kind) values (?::uuid,?,?,?) on conflict (id) do nothing",id,type,bridge,kind);return Map.of("counted",n==1);}catch(org.springframework.dao.DataIntegrityViolationException e){throw new ApiException(HttpStatus.NOT_FOUND,"BRIDGE_NOT_FOUND","다리 정보를 확인해 주세요.");}}
 private ApiException bad(String c,String m){return new ApiException(HttpStatus.BAD_REQUEST,c,m);}}
